import argparse
import fnmatch
import hashlib
import json
import os
import platform
import subprocess
import tempfile
from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
from typing import Any


REPOSITORY_ROOT = Path(__file__).resolve().parents[1]
ROOT_MANIFEST_PATH = REPOSITORY_ROOT / "crates" / "janiform-pybind" / "Cargo.toml"
DEFAULT_OUTPUT_PATH = REPOSITORY_ROOT / "THIRD_PARTY_NOTICES.txt"
LEGAL_TEXT_PATTERNS = (
    "LICENSE*",
    "LICENCE*",
    "COPYING*",
    "NOTICE*",
    "UNLICENSE*",
)
GENERATED_HEADER = (
    "This file is generated by scripts/generate_third_party_notices.py. DO NOT EDIT."
)
SUPPORTED_RUNTIME_TARGETS = (
    "x86_64-unknown-linux-gnu",
    "x86_64-pc-windows-msvc",
)
THIRD_PARTY_NOTICES_CARGO_HOME = Path(tempfile.gettempdir()) / "janiform-third-party-cargo-home"


@dataclass(frozen=True, slots=True)
class ThirdPartyPackage:
    package_id: str
    name: str
    version: str
    license_expression: str
    source: str
    repository: str | None
    homepage: str | None
    legal_files: tuple[Path, ...]


@dataclass(frozen=True, slots=True)
class LegalTextUsage:
    package_name: str
    package_version: str
    file_name: str


@dataclass(frozen=True, slots=True)
class TargetCfg:
    target_platform: str
    bare_flags: frozenset[str]
    keyed_values: dict[str, frozenset[str]]


def _collect_third_party_packages() -> tuple[ThirdPartyPackage, ...]:
    cargo_environment = _deterministic_cargo_environment()
    metadata = _load_workspace_cargo_metadata(cargo_environment)

    package_by_id: dict[str, dict[str, Any]] = {}
    reachable_external_ids: set[str] = set()

    package_by_id.update({package["id"]: package for package in metadata["packages"]})

    workspace_member_ids = set(metadata["workspace_members"])
    resolve_nodes_by_id = {node["id"]: node for node in metadata["resolve"]["nodes"]}

    root_package = _root_package(metadata["packages"])

    for target_cfg in _load_supported_target_cfgs():
        reachable_external_ids.update(
            _reachable_external_dependency_ids(
                root_package_id=root_package["id"],
                workspace_member_ids=workspace_member_ids,
                resolve_nodes_by_id=resolve_nodes_by_id,
                target_cfg=target_cfg,
            )
        )

    packages: list[ThirdPartyPackage] = []
    for package_id in sorted(
        reachable_external_ids,
        key=lambda current_id: (
            str(package_by_id[current_id]["name"]),
            str(package_by_id[current_id]["version"]),
        ),
    ):
        package = package_by_id[package_id]
        manifest_path = Path(package["manifest_path"])
        package_root = manifest_path.parent
        legal_files = _legal_files_for_package_root(package_root, package.get("license_file"))

        packages.append(
            ThirdPartyPackage(
                package_id=package_id,
                name=str(package["name"]),
                version=str(package["version"]),
                license_expression=str(package.get("license") or "UNKNOWN"),
                source=str(package.get("source") or "path"),
                repository=_optional_string(package.get("repository")),
                homepage=_optional_string(package.get("homepage")),
                legal_files=legal_files,
            )
        )

    return tuple(packages)


def _load_workspace_cargo_metadata(cargo_environment: dict[str, str]) -> dict[str, Any]:
    result = subprocess.run(
        [
            "cargo",
            "metadata",
            "--format-version",
            "1",
            "--locked",
        ],
        capture_output=True,
        check=True,
        cwd=REPOSITORY_ROOT,
        env=cargo_environment,
        text=True,
    )

    return json.loads(result.stdout)


def _deterministic_cargo_environment() -> dict[str, str]:
    cargo_environment = os.environ.copy()
    if platform.system() != "Windows":
        THIRD_PARTY_NOTICES_CARGO_HOME.mkdir(parents=True, exist_ok=True)
        cargo_environment["CARGO_HOME"] = str(THIRD_PARTY_NOTICES_CARGO_HOME)

    return cargo_environment


def _load_supported_target_cfgs() -> tuple[TargetCfg, ...]:
    return tuple(_load_target_cfg(target_platform) for target_platform in SUPPORTED_RUNTIME_TARGETS)


def _load_target_cfg(target_platform: str) -> TargetCfg:
    result = subprocess.run(
        [
            "rustc",
            "--print",
            "cfg",
            "--target",
            target_platform,
        ],
        capture_output=True,
        check=True,
        cwd=REPOSITORY_ROOT,
        text=True,
    )

    bare_flags: set[str] = set()
    keyed_values: dict[str, set[str]] = defaultdict(set)

    for raw_line in result.stdout.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        if "=" not in line:
            bare_flags.add(line)
            continue

        key, raw_value = line.split("=", maxsplit=1)
        keyed_values[key].add(_parse_cfg_string_literal(raw_value))

    return TargetCfg(
        target_platform=target_platform,
        bare_flags=frozenset(bare_flags),
        keyed_values={
            key: frozenset(values)
            for key, values in keyed_values.items()
        },
    )


def _normalize_text_newlines(value: str) -> str:
    return value.replace("\r\n", "\n").replace("\r", "\n")


def _root_package(packages: list[dict[str, Any]]) -> dict[str, Any]:
    for package in packages:
        if Path(package["manifest_path"]) == ROOT_MANIFEST_PATH:
            return package

    raise ValueError(f"Could not find root package for {ROOT_MANIFEST_PATH}")


def _reachable_external_dependency_ids(
    *,
    root_package_id: str,
    workspace_member_ids: set[str],
    resolve_nodes_by_id: dict[str, dict[str, Any]],
    target_cfg: TargetCfg,
) -> set[str]:
    queue = [root_package_id]
    visited = {root_package_id}
    reachable_external_ids: set[str] = set()

    while len(queue) > 0:
        current_id = queue.pop()

        current_node = resolve_nodes_by_id.get(current_id)
        if current_node is None:
            continue

        for dependency in current_node.get("deps", ()):
            dependency_id = dependency["pkg"]

            if not _dependency_is_runtime_relevant(dependency, target_cfg=target_cfg):
                continue
            if dependency_id in visited:
                continue

            visited.add(dependency_id)
            queue.append(dependency_id)

            if dependency_id not in workspace_member_ids:
                reachable_external_ids.add(dependency_id)

    return reachable_external_ids


def _dependency_is_runtime_relevant(
    dependency: dict[str, Any],
    *,
    target_cfg: TargetCfg,
) -> bool:
    dependency_kinds = dependency.get("dep_kinds", ())
    if len(dependency_kinds) == 0:
        return False

    return any(
        dependency_kind.get("kind") is None
        and _dependency_kind_matches_target(
            dependency_kind.get("target"),
            target_cfg=target_cfg,
        )
        for dependency_kind in dependency_kinds
    )


def _dependency_kind_matches_target(
    raw_target_expression: Any,
    *,
    target_cfg: TargetCfg,
) -> bool:
    if raw_target_expression is None:
        return True
    if not isinstance(raw_target_expression, str):
        raise ValueError(f"Unsupported cargo dependency target expression: {raw_target_expression!r}")

    target_expression = raw_target_expression.strip()
    if not target_expression:
        return True
    if not target_expression.startswith("cfg("):
        return target_expression == target_cfg.target_platform

    parser = _CfgExpressionParser(
        expression=target_expression,
        target_cfg=target_cfg,
    )
    return parser.parse()


def _parse_cfg_string_literal(raw_value: str) -> str:
    if len(raw_value) < 2 or raw_value[0] != '"' or raw_value[-1] != '"':
        raise ValueError(f"Unsupported cfg string literal: {raw_value!r}")

    return raw_value[1:-1]


class _CfgExpressionParser:
    def __init__(self, *, expression: str, target_cfg: TargetCfg) -> None:
        self._expression = expression
        self._position = 0
        self._target_cfg = target_cfg

    def parse(self) -> bool:
        self._consume_whitespace()

        if self._expression.startswith("cfg(", self._position):
            self._position += 4

            result = self._parse_expression()

            self._consume_whitespace()
            self._expect(")")
        else:
            result = self._parse_expression()

        self._consume_whitespace()
        if self._position != len(self._expression):
            raise ValueError(
                f"Unsupported trailing cfg expression content: {self._expression[self._position:]!r}"
            )

        return result

    def _parse_expression(self) -> bool:
        identifier = self._parse_identifier()
        self._consume_whitespace()

        if identifier == "all":
            return self._parse_variadic_operator(all)
        if identifier == "any":
            return self._parse_variadic_operator(any)
        if identifier == "not":
            return self._parse_not_operator()

        return self._parse_predicate(identifier)

    def _parse_variadic_operator(self, reducer: Any) -> bool:
        self._expect("(")
        self._consume_whitespace()

        values: list[bool] = []

        if not self._expression.startswith(")", self._position):
            values.append(self._parse_expression())

            while True:
                self._consume_whitespace()
                if self._try_consume(","):
                    values.append(self._parse_expression())
                    continue
                break

        self._consume_whitespace()
        self._expect(")")

        return reducer(values)

    def _parse_not_operator(self) -> bool:
        self._expect("(")

        value = self._parse_expression()

        self._consume_whitespace()
        self._expect(")")

        return not value

    def _parse_predicate(self, identifier: str) -> bool:
        self._consume_whitespace()
        if not self._try_consume("="):
            return identifier in self._target_cfg.bare_flags

        self._consume_whitespace()

        expected_value = self._parse_string_literal()

        return expected_value in self._target_cfg.keyed_values.get(identifier, frozenset())

    def _parse_identifier(self) -> str:
        self._consume_whitespace()

        start = self._position
        while self._position < len(self._expression):
            current_char = self._expression[self._position]
            if current_char.isalnum() or current_char == "_":
                self._position += 1
                continue
            break

        if start == self._position:
            raise ValueError(
                f"Unsupported cfg expression near: {self._expression[self._position:]!r}"
            )

        return self._expression[start:self._position]

    def _parse_string_literal(self) -> str:
        if self._position >= len(self._expression) or self._expression[self._position] != '"':
            raise ValueError(
                f"Unsupported cfg string literal near: {self._expression[self._position:]!r}"
            )

        start = self._position
        self._position += 1

        while self._position < len(self._expression):
            current_char = self._expression[self._position]
            self._position += 1
            if current_char == '"':
                return self._expression[start + 1:self._position - 1]

        raise ValueError(f"Unterminated cfg string literal in: {self._expression!r}")

    def _consume_whitespace(self) -> None:
        while self._position < len(self._expression) and self._expression[self._position].isspace():
            self._position += 1

    def _expect(self, token: str) -> None:
        if not self._try_consume(token):
            raise ValueError(
                f"Expected {token!r} in cfg expression: {self._expression!r}"
            )

    def _try_consume(self, token: str) -> bool:
        self._consume_whitespace()
        if self._expression.startswith(token, self._position):
            self._position += len(token)
            return True

        return False


def _legal_files_for_package_root(
    package_root: Path,
    declared_license_file: Any,
) -> tuple[Path, ...]:
    legal_files: dict[str, Path] = {}
    if isinstance(declared_license_file, str) and declared_license_file.strip():
        declared_path = (package_root / declared_license_file).resolve()
        if declared_path.is_file():
            legal_files[declared_path.name.lower()] = declared_path

    for candidate_path in sorted(package_root.iterdir()):
        if not candidate_path.is_file():
            continue
        if _matches_legal_text_pattern(candidate_path.name):
            legal_files[candidate_path.name.lower()] = candidate_path.resolve()

    return tuple(
        sorted(
            legal_files.values(),
            key=lambda path: path.name.lower(),
        )
    )


def _matches_legal_text_pattern(file_name: str) -> bool:
    normalized_file_name = file_name.lower()
    return any(
        fnmatch.fnmatch(normalized_file_name, pattern.lower())
        for pattern in LEGAL_TEXT_PATTERNS
    )


def _render_third_party_notices(third_party_packages: tuple[ThirdPartyPackage, ...]) -> str:
    lines: list[str] = [
        GENERATED_HEADER,
        "",
        "Janiform Third-Party Notices",
        "============================",
        "",
        (
            "This file inventories the non-workspace Cargo dependency closure for "
            "`crates/janiform-pybind`, which is the Rust extension packaged inside the Janiform wheel."
        ),
        "Python dependencies that are distributed separately from the Janiform wheel are not included here.",
        "The inventory is intentionally conservative and may include build-support or macro-support crates",
        "from that locked Cargo dependency closure in addition to code linked into the final extension.",
        "",
        "Package Inventory",
        "-----------------",
        "",
    ]

    packages_without_legal_files: list[ThirdPartyPackage] = []
    for package in third_party_packages:
        lines.append(f"- {package.name} {package.version}")
        lines.append(f"  license: {package.license_expression}")
        lines.append(f"  source: {package.source}")

        if package.repository is not None:
            lines.append(f"  repository: {package.repository}")
        elif package.homepage is not None:
            lines.append(f"  homepage: {package.homepage}")

        if len(package.legal_files) == 0:
            lines.append("  legal files: none found in the crate source tree")
            packages_without_legal_files.append(package)
        else:
            lines.append(
                "  legal files: " + ", ".join(path.name for path in package.legal_files)
            )

        lines.append("")

    lines.append("Bundled License And Notice Texts")
    lines.append("-------------------------------")
    lines.append("")

    grouped_texts = _group_legal_texts(third_party_packages)
    for group_index, grouped_text in enumerate(grouped_texts, start=1):
        lines.append("=" * 79)
        lines.append(f"Text {group_index:03d}")
        lines.append("-" * 79)
        lines.append("Applies to:")

        for usage in grouped_text["usages"]:
            lines.append(
                f"- {usage.package_name} {usage.package_version} ({usage.file_name})"
            )

        lines.append("")
        lines.extend(grouped_text["text"].rstrip("\n").splitlines())
        lines.append("")

    if len(packages_without_legal_files) > 0:
        lines.append("=" * 79)
        lines.append("Packages Without Bundled License Files")
        lines.append("-" * 79)
        lines.append("The following packages exposed license metadata through Cargo metadata but did not ship")
        lines.append("a top-level NOTICE/LICENSE/COPYING file in the fetched crate source tree:")
        lines.append("")

        for package in packages_without_legal_files:
            lines.append(
                f"- {package.name} {package.version}: {package.license_expression}"
            )

        lines.append("")

    return "\n".join(lines).rstrip() + "\n"


def _group_legal_texts(
    third_party_packages: tuple[ThirdPartyPackage, ...],
) -> list[dict[str, Any]]:
    grouped_usages: dict[str, list[LegalTextUsage]] = defaultdict(list)
    grouped_texts: dict[str, str] = {}

    for package in third_party_packages:
        for legal_file in package.legal_files:
            legal_text = legal_file.read_text(encoding="utf-8", errors="replace")
            normalized_text = legal_text.replace("\r\n", "\n").replace("\r", "\n")

            text_hash = hashlib.sha256(normalized_text.encode("utf-8")).hexdigest()

            grouped_texts[text_hash] = normalized_text
            grouped_usages[text_hash].append(
                LegalTextUsage(
                    package_name=package.name,
                    package_version=package.version,
                    file_name=legal_file.name,
                )
            )

    grouped_entries: list[dict[str, Any]] = []
    for text_hash, text in grouped_texts.items():
        usages = sorted(
            grouped_usages[text_hash],
            key=lambda usage: (
                usage.package_name,
                usage.package_version,
                usage.file_name.lower(),
            ),
        )
        grouped_entries.append({"text": text, "usages": usages})

    grouped_entries.sort(
        key=lambda entry: (
            entry["usages"][0].package_name,
            entry["usages"][0].package_version,
            entry["usages"][0].file_name.lower(),
        )
    )

    return grouped_entries


def _optional_string(value: Any) -> str | None:
    if isinstance(value, str) and value.strip():
        return value

    return None


def main() -> int:
    argument_parser = argparse.ArgumentParser(
        description=(
            "Generate or validate THIRD_PARTY_NOTICES.txt for the Rust dependency closure "
            "behind the janiform wheel extension."
        )
    )
    argument_parser.add_argument(
        "--check",
        action="store_true",
        help="Exit with a non-zero status when THIRD_PARTY_NOTICES.txt is out of date.",
    )
    argument_parser.add_argument(
        "--output-path",
        default=str(DEFAULT_OUTPUT_PATH),
        help="Path where the generated notices file should be written.",
    )
    arguments = argument_parser.parse_args()

    output_path = Path(arguments.output_path)
    third_party_packages = _collect_third_party_packages()
    rendered_notices = _render_third_party_notices(third_party_packages)

    if arguments.check:
        existing = (
            _normalize_text_newlines(output_path.read_text(encoding="utf-8"))
            if output_path.exists()
            else None
        )
        if existing != rendered_notices:
            print(f"{output_path.relative_to(REPOSITORY_ROOT)} is out of date.")
            print("Regenerate it with `python scripts/generate_third_party_notices.py`.")

            return 1

        return 0

    with output_path.open("w", encoding="utf-8", newline="\n") as output_file:
        output_file.write(rendered_notices)

    print(f"Generated: {str(output_path.relative_to(REPOSITORY_ROOT))}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
